'use strict';
// Tako desktop prototype — the spec for the settings work: what each control maps to in native 526,
// and the requested «сессия» level written down as an extension, not as something Tako already does.
{
  const notes = $('#notes'), dl = notes.querySelector('dl');
  const dd = (name, html) => { const d = [...dl.querySelectorAll('dt')].find(x => x.textContent === name); if (d) d.nextElementSibling.innerHTML = html; };
  dd('темы', 'Каталог — 10 встроенных тем Tako (swift/Resources/themes: TakoCore, Tako Dawn, Ember, Forest, Ink, Night, Ocean, Paper, Slate, Violet) и свои темы из папки themes рядом с конфигом. Выбор темы применяется сразу. Встроенная не меняется: «Дублировать…» → имя (проверка как в ThemePresetStore: пусто, пробелы по краям, «.», «/», «..», «tako», кавычки, занятое имя) → редактор с черновиком и живым предпросмотром на терминалах выбранного уровня → «Сохранить тему» (создаёт и выбирает для уровня) или «Отменить» (вид возвращается). Свою тему можно изменить, переименовать (ссылки переезжают) и удалить (показано, где она выбрана). Разделы редактора: Цвета, ANSI (16), Шрифт (семейство, размер 6–72, по раскрытию веса 100–900 шаг 50, шрифты жирного и курсива, высота строки), Курсор и выделение, Конфиг — текстом с проверкой строк.');
  dd('наследование', 'Оформление идёт по цепочке Общие → workspace → терминал (как Appearance.json: workspaces/panes по UUID). Уровень либо выбирает тему (своё оформление этого уровня при этом сбрасывается — как applyPreset), либо переопределяет поля: шрифт, размер, фон, текст, курсор, выделение. Значение ищется снизу вверх: первый уровень, где есть поле или тема. «↺» удаляет переопределение — значение снова приходит сверху; копирования вниз нет. Пример в демо: workspace Default = Night, терминал claude · auth = Paper; сменил Default на Forest — fish стал Forest, claude остался Paper; «Наследовать» у claude — тоже Forest. Быстро: правый клик по workspace, шапке или телу терминала → «Оформление ▸» (6 тем, недавние первыми, ✓ у текущей, «Наследовать», «Все темы…», «Настроить…»). Окно настроек по центру, выбранный уровень — крошками сверху, не прыгает.');
  dd('настройки', 'Разделы: Общее, Оформление, Терминал, Окна и workspace, Quick Terminal, Клавиши, Агенты, Уведомления и доступы, Дополнительно; поиск сверху находит настройку, ключ конфига или действие клавиш. Каждая строка: что делает, ключ конфига, когда применяется, ↺ к стандартному. Только Оформление зависит от уровня; остальное — для всего приложения, и это написано. Клавиши: список действий Tako со стандартными сочетаниями, поиск по названию и сочетанию («⇧⌘D», «cmd+d»), «Изменённые», запись по щелчку: нужен модификатор или F1–F12, Esc — отмена, ⌫ — стандартное; занятое сочетание называет владельца и спрашивает «Переназначить» / «Отмена». Пока идёт запись, нажатие не выполняет команду и не уходит в терминал.');
  const R = [
    ['Тема уровня', 'theme · Appearance.json', 'Оформление', 'уровень', 'сразу'],
    ['Шрифт, размер, фон, текст, курсор, выделение уровня', 'font-family, font-size, background, foreground, cursor-color, selection-background', 'Оформление', 'уровень', 'сразу'],
    ['Своя тема', 'themes/<имя> · ThemePresetStore', 'Оформление › редактор', 'файл темы', 'по «Сохранить»'],
    ['Цвета и ANSI темы', 'background … palette = N=#RRGGBB', 'редактор › Цвета, ANSI', 'тема', 'черновик → «Сохранить»'],
    ['Начертания', 'font-weight[-bold|-italic|-bold-italic], font-family-bold…', 'редактор › Шрифт', 'тема', 'черновик'],
    ['Курсор и выделение темы', 'cursor-style, cursor-style-blink, cursor-opacity, selection-*', 'редактор › Курсор', 'тема', 'черновик'],
    ['Спрашивать перед закрытием', 'confirm-close-surface', 'Общее', 'приложение', 'сразу'],
    ['Новый терминал в той же папке', 'window-inherit-working-directory', 'Общее', 'приложение', 'для новых'],
    ['Новые окна берут размер шрифта', 'window-inherit-font-size', 'Общее', 'приложение', 'для новых окон'],
    ['Форма и мигание курсора', 'cursor-style, cursor-style-blink', 'Терминал', 'приложение (тема сильнее)', 'сразу'],
    ['Прятать указатель', 'mouse-hide-while-typing', 'Терминал', 'приложение', 'сразу'],
    ['Копировать выделенное', 'copy-on-select', 'Терминал', 'приложение', 'сразу'],
    ['Подтверждать вставку', 'safe-paste', 'Терминал', 'приложение', 'сразу'],
    ['Интеграция с шеллом', 'shell-integration', 'Терминал', 'приложение', 'для новых терминалов'],
    ['Окно при смене workspace', 'workspace-sync-window-frame (alias workspace-inherit-window-frame)', 'Окна и workspace', 'приложение', 'при переключении'],
    ['Размытие фона', 'background-blur 0–60', 'Окна и workspace', 'приложение', 'сразу'],
    ['Quick Terminal', 'quick-terminal-position, quick-terminal-autohide', 'Quick Terminal', 'приложение', 'при показе'],
    ['Сочетания', 'keybind = trigger=action · defaultKeyboardShortcuts', 'Клавиши', 'приложение', 'сразу'],
    ['Цвета статусов', 'tab-status-color-working|waiting|done|error|idle', 'Дополнительно', 'приложение', 'сразу'],
    ['Навык агентам, доступы', 'SetupAgentService, TerminalPermissionService', 'Агенты, Доступы', 'Mac / пользователь', 'по действию'],
    ['Стиль вкладок', 'tab-style', 'не показан', '—', 'верхних вкладок в дизайне нет'],
    ['Уровень «сессия»', 'нет в 526', 'только с «показать идеи»', 'расширение', 'см. ниже'],
  ];
  dl.insertAdjacentHTML('afterend', `<h4>Настройки: покрытие</h4><p class="rt-n">Настройка → ключ в Tako 526 → раздел макета → область → когда применяется.</p>
    <table class="rt">${R.map(r => `<tr><td>${r[0]}</td><td>${r[1]} · ${r[2]}</td><td class="${r[3] === 'расширение' ? 'idea' : r[2] === 'не показан' ? 'ask' : 'ok'}">${r[3]} · ${r[4]}</td></tr>`).join('')}</table>
    <h4>Уровень «сессия» — запрошенное расширение</h4><p class="rt-n">В Tako 526 его нет: AppearanceScope знает только workspace и pane. В основном пути — три уровня; сессия видна с «показать идеи» как пунктирная крошка «расширение» и пункт «Оформление сессии» в меню сессии.</p>
    <p class="rt-n">Предлагаемая семантика: устойчивый ID сессии (вкладки), который переживает перезапуск и перенос; приоритет терминал › сессия › workspace › Общие; новый терминал в сессии без своего значения наследует сессию; «↺» удаляет поле только у сессии; перенос сессии в другой workspace сохраняет её собственное оформление, а терминалы, наследовавшие workspace, получают прежний вид своим (как сейчас для pane). Хранение — отдельная карта sessions в Appearance.json с переходом на версию 2; никакого массового копирования значений в терминалы.</p>`);
  for (const td of notes.querySelectorAll('.rt td')) if (td.textContent.includes('каталог из 24 тем')) { td.textContent = 'есть · 10 встроенных тем Tako и свои темы'; td.className = 'ok'; }
}
